<script setup>
import {onMounted,ref} from "vue";import {useRouter} from "vue-router";import {NButton,NEmpty,NInput,NSelect,NTag,NDrawer,NDrawerContent,useMessage} from "naive-ui";
import PageShell from "../components/PageShell.vue";import Panel from "../components/Panel.vue";import {auditApi} from "../api.js";import {dateText,resultOf,actionText,actorText} from "../display.js";import {openSession} from "../navigation.js";
const router=useRouter(),message=useMessage(),loading=ref(false),error=ref(""),rows=ref([]),total=ref(0),q=ref(""),actorType=ref(null),from=ref(""),to=ref(""),page=ref(1),detail=ref(null),detailOpen=ref(false);const size=20;
const sources=[{label:'全部来源',value:null},{label:'成员',value:'user'},{label:'系统',value:'system'},{label:'开放 API',value:'api_key'},{label:'匿名',value:'anonymous'}];
async function load(reset=false){if(reset)page.value=1;loading.value=true;error.value="";try{const p=new URLSearchParams({limit:String(size),offset:String((page.value-1)*size)});if(q.value.trim())p.set('q',q.value.trim());if(actorType.value)p.set('actorType',actorType.value);if(from.value)p.set('from',new Date(from.value).toISOString());if(to.value)p.set('to',new Date(to.value).toISOString());const r=await auditApi.list(p.toString());rows.value=r.items??[];total.value=r.total??0;}catch(e){error.value=e.message;}finally{loading.value=false;}}
function inspect(item){detail.value=item;detailOpen.value=true;}
async function visit(){try{await openSession(router,detail.value.targetId);detailOpen.value=false;}catch(e){message.error(e.message);}}
onMounted(()=>load());
</script><template><PageShell title="审计" subtitle="检索成员操作和业务执行记录，查看具体目标与结果" :loading="loading" :error="error"><div class="toolbar"><n-input v-model:value="q" placeholder="搜索动作、目标或关键词" class="search" clearable @keyup.enter="load(true)"/><n-select v-model:value="actorType" :options="sources" style="width:150px"/><label class="secondary">开始 <input v-model="from" aria-label="开始时间" type="datetime-local"/></label><label class="secondary">结束 <input v-model="to" aria-label="结束时间" type="datetime-local"/></label><n-button type="primary" @click="load(true)">查询</n-button><n-button @click="q='';actorType=null;from='';to='';load(true)">重置</n-button></div><Panel :meta="`共 ${total} 条`" title="操作记录" :padded="false"><n-empty v-if="!rows.length&&!loading" description="没有匹配的审计记录" class="empty-state"/><div v-else class="table-wrap"><table class="data-table audit-table"><thead><tr><th>时间</th><th>来源</th><th>动作</th><th>目标</th><th>结果</th><th>详情</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{dateText(item.createdAt)}}</td><td>{{actorText(item.actorType)}}<span class="secondary">{{item.actorId||'—'}}</span></td><td>{{actionText(item.action)}}<span class="secondary">{{item.action}}</span></td><td>{{item.targetType||'—'}}<span class="secondary">{{item.targetId||'—'}}</span></td><td><n-tag :type="resultOf(item).type">{{resultOf(item).label}}</n-tag></td><td><n-button size="small" @click="inspect(item)">查看详情</n-button></td></tr></tbody></table></div></Panel><div class="pagination"><span class="secondary">共 {{total}} 条 · 第 {{page}} 页</span><n-button :disabled="page===1||loading" @click="page--;load()">上一页</n-button><n-button :disabled="page*size>=total||loading" @click="page++;load()">下一页</n-button></div><n-drawer v-model:show="detailOpen" :width="620"><n-drawer-content title="审计详情" closable><template v-if="detail"><dl class="detail-grid"><dt>动作</dt><dd>{{actionText(detail.action)}}（{{detail.action}}）</dd><dt>发生时间</dt><dd>{{dateText(detail.createdAt)}}</dd><dt>来源</dt><dd>{{actorText(detail.actorType)}} · {{detail.actorId||'—'}}</dd><dt>目标</dt><dd>{{detail.targetType}} · {{detail.targetId||'—'}}</dd><dt>结果</dt><dd>{{resultOf(detail).label}}</dd></dl><n-button v-if="detail.targetType==='session'&&detail.targetId" @click="visit">打开关联会话</n-button><h4>记录详情</h4><pre class="json-view">{{JSON.stringify(detail.detail??{},null,2)}}</pre></template></n-drawer-content></n-drawer></PageShell></template>
